// Configure your Google Ads Lead Form extension to POST to this webhook.
// Expected fields: user_column_data (array of {column_id, string_value}).
const body = items[0].json.body || items[0].json;
const arr = body.user_column_data || [];
const pick = (id) => (arr.find(x => x.column_id === id)?.string_value) || '';
return [{ json: {
  name: pick('FULL_NAME') || pick('NAME'),
  email: pick('EMAIL'),
  phone: pick('PHONE_NUMBER') || pick('PHONE'),
  company: pick('COMPANY_NAME') || '',
  message: pick('USER_NOTES') || '',
  source: 'google',
  territory: pick('CITY') || 'Bengaluru',
  orgId: $env.ASOFTECH_ORG_ID ,
  meta: { campaign_id: body.campaign_id, gcl_id: body.gcl_id }
}}];
